#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_LEN 64

int levenshtein(const char *s, const char *t) {
    size_t n = strlen(s);
    size_t m = strlen(t);
    // DP table of size (n+1)*(m+1)
    int dp[MAX_LEN + 1][MAX_LEN + 1];
    for (size_t i = 0; i <= n; ++i) dp[i][0] = (int)i;
    for (size_t j = 0; j <= m; ++j) dp[0][j] = (int)j;
    for (size_t i = 1; i <= n; ++i) {
        for (size_t j = 1; j <= m; ++j) {
            int cost = (s[i-1] == t[j-1]) ? 0 : 1;
            int del = dp[i-1][j] + 1;      // deletion
            int ins = dp[i][j-1] + 1;      // insertion
            int sub = dp[i-1][j-1] + cost; // substitution
            int min = del;
            if (ins < min) min = ins;
            if (sub < min) min = sub;
            dp[i][j] = min;
        }
    }
    return dp[n][m];
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *a = argv[1];
    const char *b = argv[2];
    size_t la = strlen(a);
    size_t lb = strlen(b);
    if (la > MAX_LEN || lb > MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }
    int dist = levenshtein(a, b);
    printf("%d\n", dist);
    return 0;
}
